using System;
using System.Collections.Generic;
using Framework.AI.Perception;

namespace Framework.AI.Memory
{
    /// <summary>
    /// 対象ごとの最終認識情報を管理する。
    /// </summary>
    /// <typeparam name="TPosition">認識位置を表現する型</typeparam>
    /// <remarks>
    /// 記憶の信頼度は取得時に計算する。
    /// 自動更新や自動削除は行わない。
    /// すべての時刻には同一の時間基準を使用すること。
    /// </remarks>
    public sealed class PerceptionMemory<TPosition>
    {
        /// <summary>
        /// 対象ごとの最終認識情報。
        /// </summary>
        private readonly Dictionary<Guid,
            PerceptionStimulus<TPosition>> memories =
            new Dictionary<Guid,
                PerceptionStimulus<TPosition>>();

        /// <summary>
        /// 期限切れ記憶の削除に使用する作業用リスト。
        /// </summary>
        private readonly List<Guid> removalBuffer =
            new List<Guid>();

        /// <summary>
        /// 記憶保持時間。単位は秒。
        /// </summary>
        private double retentionDuration;

        /// <summary>
        /// 保存されている記憶の件数を取得する。
        /// 期限切れの記憶も含む。
        /// </summary>
        public int Count => memories.Count;

        /// <summary>
        /// 記憶保持時間を取得する。単位は秒。
        /// </summary>
        public double RetentionDuration => retentionDuration;

        /// <summary>
        /// 認識記憶を生成する。
        /// </summary>
        /// <param name="retentionDuration">
        /// 記憶保持時間。単位は秒。
        /// </param>
        public PerceptionMemory(
            double retentionDuration = 10d)
        {
            SetRetentionDuration(retentionDuration);
        }

        /// <summary>
        /// 記憶保持時間を変更する。
        /// </summary>
        /// <param name="duration">記憶保持時間。単位は秒</param>
        /// <exception cref="ArgumentOutOfRangeException">
        /// 保持時間が有限の正数ではない場合に発生する。
        /// </exception>
        public void SetRetentionDuration(double duration)
        {
            if (double.IsNaN(duration) ||
                double.IsInfinity(duration) ||
                duration <= 0d)
            {
                throw new ArgumentOutOfRangeException(
                    nameof(duration));
            }

            retentionDuration = duration;
        }

        /// <summary>
        /// 認識情報を記憶する。
        /// </summary>
        /// <param name="stimulus">記憶する認識情報</param>
        /// <returns>記憶の保存または更新に成功した場合はtrue</returns>
        /// <remarks>
        /// 無効な情報、対象不明の情報、信頼度0の情報は保存しない。
        /// 既存情報より古い情報は保存しない。
        /// 同時刻の場合は信頼度が高い情報を優先する。
        /// </remarks>
        public bool Remember(
            PerceptionStimulus<TPosition> stimulus)
        {
            if (!stimulus.IsValid ||
                stimulus.SourceId == Guid.Empty ||
                stimulus.Confidence <= 0f)
            {
                return false;
            }

            if (memories.TryGetValue(
                stimulus.SourceId,
                out PerceptionStimulus<TPosition> previous))
            {
                // 古い認識情報による上書きを防止する。
                if (stimulus.Timestamp < previous.Timestamp)
                {
                    return false;
                }

                // 同時刻では信頼度が高い情報を優先する。
                if (stimulus.Timestamp == previous.Timestamp &&
                    stimulus.Confidence <= previous.Confidence)
                {
                    return false;
                }
            }

            memories[stimulus.SourceId] = stimulus;

            return true;
        }

        /// <summary>
        /// 保存されている最終認識情報を取得する。
        /// </summary>
        /// <param name="sourceId">認識対象の識別子</param>
        /// <param name="stimulus">取得した認識情報</param>
        /// <returns>保存された記憶が存在する場合はtrue</returns>
        /// <remarks>
        /// 期限切れの記憶も取得対象とする。
        /// </remarks>
        public bool TryGetLastObservation(
            Guid sourceId,
            out PerceptionStimulus<TPosition> stimulus)
        {
            return memories.TryGetValue(
                sourceId,
                out stimulus);
        }

        /// <summary>
        /// 現在も有効な認識記憶を取得する。
        /// </summary>
        /// <param name="sourceId">認識対象の識別子</param>
        /// <param name="currentTime">現在時刻。単位は秒</param>
        /// <param name="stimulus">取得した認識情報</param>
        /// <param name="confidence">現在の記憶信頼度</param>
        /// <returns>有効な記憶が存在する場合はtrue</returns>
        /// <remarks>
        /// 失敗時は認識情報の既定値と信頼度0を返す。
        /// 未来の認識情報は取得対象としない。
        /// </remarks>
        public bool TryRecall(
            Guid sourceId,
            double currentTime,
            out PerceptionStimulus<TPosition> stimulus,
            out float confidence)
        {
            ValidateTime(currentTime);

            stimulus = default(
                PerceptionStimulus<TPosition>);

            confidence = 0f;

            if (!memories.TryGetValue(
                sourceId,
                out PerceptionStimulus<TPosition> stored))
            {
                return false;
            }

            if (currentTime < stored.Timestamp)
            {
                return false;
            }

            float currentConfidence =
                CalculateConfidence(stored, currentTime);

            if (currentConfidence <= 0f)
            {
                return false;
            }

            stimulus = stored;
            confidence = currentConfidence;

            return true;
        }

        /// <summary>
        /// 指定対象に対する現在の記憶信頼度を取得する。
        /// </summary>
        /// <param name="sourceId">認識対象の識別子</param>
        /// <param name="currentTime">現在時刻。単位は秒</param>
        /// <returns>0から1の記憶信頼度</returns>
        public float GetConfidence(
            Guid sourceId,
            double currentTime)
        {
            TryRecall(
                sourceId,
                currentTime,
                out _,
                out float confidence);

            return confidence;
        }

        /// <summary>
        /// 期限切れとなった記憶を削除する。
        /// </summary>
        /// <param name="currentTime">現在時刻。単位は秒</param>
        /// <returns>削除した記憶の件数</returns>
        public int RemoveExpired(double currentTime)
        {
            ValidateTime(currentTime);

            removalBuffer.Clear();

            // 列挙中のDictionary変更を避ける。
            foreach (var pair in memories)
            {
                double elapsed =
                    currentTime - pair.Value.Timestamp;

                if (elapsed >= retentionDuration)
                {
                    removalBuffer.Add(pair.Key);
                }
            }

            int removedCount = removalBuffer.Count;

            for (int i = 0; i < removedCount; i++)
            {
                memories.Remove(removalBuffer[i]);
            }

            removalBuffer.Clear();

            return removedCount;
        }

        /// <summary>
        /// 指定対象の記憶を削除する。
        /// </summary>
        /// <param name="sourceId">認識対象の識別子</param>
        /// <returns>削除に成功した場合はtrue</returns>
        public bool Forget(Guid sourceId)
        {
            return memories.Remove(sourceId);
        }

        /// <summary>
        /// すべての認識記憶を削除する。
        /// </summary>
        public void Clear()
        {
            memories.Clear();
            removalBuffer.Clear();
        }

        /// <summary>
        /// 経過時間に応じた記憶信頼度を計算する。
        /// </summary>
        /// <param name="stimulus">保存された認識情報</param>
        /// <param name="currentTime">現在時刻。単位は秒</param>
        /// <returns>減衰後の記憶信頼度</returns>
        private float CalculateConfidence(
            PerceptionStimulus<TPosition> stimulus,
            double currentTime)
        {
            double elapsed =
                currentTime - stimulus.Timestamp;

            if (elapsed >= retentionDuration)
            {
                return 0f;
            }

            // 認識時の信頼度に線形減衰を適用する。
            double remainingRate =
                1d - elapsed / retentionDuration;

            return (float)(
                stimulus.Confidence * remainingRate);
        }

        /// <summary>
        /// 時刻が有効な値であることを検証する。
        /// </summary>
        /// <param name="time">検証対象の時刻。単位は秒</param>
        /// <exception cref="ArgumentOutOfRangeException">
        /// 時刻が有限の非負数ではない場合に発生する。
        /// </exception>
        private static void ValidateTime(double time)
        {
            if (double.IsNaN(time) ||
                double.IsInfinity(time) ||
                time < 0d)
            {
                throw new ArgumentOutOfRangeException(
                    nameof(time));
            }
        }
    }
}
